  'settings.formatLocale.title': { fr: 'Format des dates et des nombres du document', en: 'Date and number format of the document' },
  'settings.formatLocale.intro': {
    fr: 'Format dans lequel les dates et les nombres s’écrivent dans le document, la Lecture, les PDF et les emails : ordre du jour et du mois, séparateurs, noms des mois. Ce choix est gardé dans le document : tout le monde obtient le même texte, quelle que soit la langue de son interface. Une variable de date ou de nombre garde le format que le document avait quand elle a été ajoutée : le choix ne touche que les anciennes variables, qui n’en avaient pas, et celles à venir. L’écriture en toutes lettres (« Lettres ») n’existe qu’en français et en anglais.',
    en: 'Format in which dates and numbers are written in the document, Read mode, PDFs and emails: order of day and month, separators, month names. This choice is kept in the document: everyone gets the same text, whatever the language of their interface. A date or number variable keeps the format the document had when it was added: the choice only affects older variables, which had none, and future ones. Writing out in full (“Words”) only exists in French and English.',
  },
  'settings.formatLocale.auto': { fr: 'Automatique', en: 'Automatic' },
  'settings.formatLocale.hintChosen': {
    fr: 'Ce document écrit ses dates et ses nombres au format « {name} », pour tout le monde.',
    en: 'This document writes its dates and numbers in the “{name}” format, for everyone.',
  },
  'settings.formatLocale.hintGrist': {
    fr: 'Automatique : ce document est réglé dans Grist (Paramètres du document, Locale) : ses dates et ses nombres s’écrivent au format « {name} » pour tout le monde.',
    en: 'Automatic: this document is set up in Grist (Document settings, Locale): its dates and numbers are written in the “{name}” format for everyone.',
  },
  'settings.formatLocale.hintInterface': {
    fr: 'Automatique : chaque personne voit les dates et les nombres au format de la langue de son interface (ici : « {name} »). Choisissez un format pour que le document écrive pareil chez tout le monde.',
    en: 'Automatic: each person sees dates and numbers in the format of their own interface language (here: “{name}”). Choose a format so the document is written the same for everyone.',
  },
  'settings.formatLocale.locked': { fr: 'Vous êtes en lecture seule : ce réglage est verrouillé.', en: 'You are read-only: this setting is locked.' },
  'settings.formatLocale.failed': { fr: 'Ce choix n’a pas pu être enregistré dans le document : Grist l’a refusé.', en: 'This choice could not be saved in the document: Grist refused it.' },
  'settings.mailClient.intro': { fr: 'Logiciel de messagerie qui ouvre le lien du mode Email. Gardez Standard, sauf si vos emails s’ouvrent dans Zimbra : « Zimbra » si votre poste est déjà réglé pour l’ouvrir, « Webmail Zimbra » pour l’ouvrir directement dans un onglet, sans rien régler sur le poste.', en: 'Mail program that opens the Email mode link. Keep Standard unless your emails open in Zimbra: “Zimbra” if your computer is already set to open it, “Zimbra webmail” to open it straight in a tab, with nothing to set on the computer.' },
  'settings.mailClient.standard': { fr: 'Standard', en: 'Standard' },
  'settings.mailClient.zimbra': { fr: 'Zimbra', en: 'Zimbra' },
  'settings.mailClient.zimbraNote': {
    fr: 'Zimbra lit mal « & », « < », « > » et « + » dans le lien : « & » s’y affiche « &amp; » et « + » devient une espace. Avec Zimbra, l’objet et le corps les écrivent en forme large (＆ ＜ ＞ ＋) : ils s’affichent bien, mais le lien est un peu plus long. Dans le corps, une adresse web contenant « & » ou une adresse email contenant « + » n’est plus utilisable telle quelle.',
    en: 'Zimbra misreads “&”, “<”, “>” and “+” in the link: “&” shows as “&amp;” and “+” becomes a space. With Zimbra, the subject and body write them in full-width form (＆ ＜ ＞ ＋): they display correctly, but the link is a little longer. In the body, a web address containing “&” or an email address containing “+” can no longer be used as is.',
  },
  'settings.mailClient.perBrowser': { fr: 'Ce choix est propre à ce navigateur, comme la langue et le thème.', en: 'This choice is specific to this browser, like the language and the theme.' },
  // L'avertissement « Email trop long » (js/mailto-export.js:getLengthWarning, js/main-export.js:onCreateEmail) : allumé au départ ; la case « Ne plus afficher » de la fenêtre l'éteint, cette case le rallume.
  'settings.emailLength.title': { fr: 'Email trop long', en: 'Email too long' },
  'settings.emailLength.label': { fr: 'Prévenir quand un email est trop long', en: 'Warn when an email is too long' },
  'settings.emailLength.hint': {
    fr: 'Quand le lien de l’email dépasse la limite conseillée (la jauge de la barre devient rouge), « Créer l’email » demande confirmation : certains logiciels de messagerie, Outlook notamment, tronquent un message trop long. Éteint (par la case « Ne plus afficher cet avertissement » de la fenêtre « Email trop long »), le lien s’ouvre sans question ; la jauge reste rouge et le brouillon s’ouvre tel quel.',
    en: 'When the email link goes over the recommended limit (the gauge in the bar turns red), “Create email” asks for confirmation: some mail clients, Outlook in particular, truncate a message that is too long. Off (by the “Don’t show this warning again” box of the “Email too long” window), the link opens without a question; the gauge stays red and the draft opens as it is.',
  },
  'settings.emailLength.on': { fr: 'allumé', en: 'on' },
  'settings.emailLength.off': { fr: 'éteint', en: 'off' },
  'settings.triggerKey.intro': { fr: 'Caractère à taper dans le texte pour ouvrir la liste des variables et des Puces.', en: 'Character to type in the text to open the list of variables and Chips.' },
  'settings.triggerKey.name': { fr: 'Caractère d’insertion', en: 'Insert character' },
  'settings.pageMargins.intro': { fr: 'Marges de page (mm) : propres à ce modèle, appliquées à l’aperçu et aux exports PDF et DOCX.', en: 'Page margins (mm): specific to this template, applied to the preview and to PDF and DOCX exports.' },
  'settings.pageMargins.macroNote': { fr: 'Macro-modèle : ces marges priment sur celles des modèles assemblés, dans l’aperçu comme dans les exports. Les marges propres à un modèle ne servent que lorsqu’on l’ouvre seul.', en: 'Macro template: these margins take precedence over those of the assembled templates, in the preview and in the exports. A template’s own margins only apply when it is opened on its own.' },
