  'news.format.name': { fr: 'Une mise en forme du texte plus fine', en: 'Finer text formatting' },
  'news.format.text': { fr: 'Le menu « Aa » : exposant, indice, petites capitales, ombre, contour, espacement. Le bouton Souligné : double, pointillé, tireté, ondulé. Et le texte de droite à gauche, jusque dans Word.', en: 'The “Aa” menu: superscript, subscript, small capitals, shadow, outline, spacing. The Underline button: double, dotted, dashed, wavy. And right-to-left text, all the way to Word.' },
  'news.format.alt': { fr: 'Le menu « Aa » ouvert à côté d’un texte à ombre, contour, petites capitales et soulignements', en: 'The “Aa” menu open next to text with shadow, outline, small capitals and underlines' },
  'news.tables.name': { fr: 'Des tableaux comme dans une grille', en: 'Tables as in a grid' },
  'news.tables.text': { fr: 'Des lettres au-dessus des colonnes, des numéros devant les lignes : un clic les choisit, tirer un bord règle leur taille, et la barre pose les bordures et l’alignement vertical.', en: 'Letters above the columns, numbers beside the rows: one click picks them, dragging an edge sets their size, and the bar sets the borders and the vertical alignment.' },
  'news.tables.alt': { fr: 'Un tableau de document avec ses lettres, ses numéros et sa barre d’outils flottante', en: 'A document table with its letters, its numbers and its floating toolbar' },
  'news.pages.name': { fr: 'Portrait et paysage dans un même document', en: 'Portrait and landscape in one document' },
  'news.pages.text': { fr: 'Un macro-modèle peut mêler des pages en portrait et en paysage : chaque modèle garde le sens de sa page dans la Lecture, l’impression, le PDF et le Word.', en: 'A macro-template can mix portrait and landscape pages: each template keeps the direction of its page in Read mode, printing, the PDF and Word.' },
  'news.pages.alt': { fr: 'Le résumé d’un macro-modèle dont l’annexe 1 est en paysage, et ses trois pages : portrait, paysage, portrait', en: 'The summary of a macro-template whose annex 1 is landscape, and its three pages: portrait, landscape, portrait' },
  'news.conditions.name': { fr: 'Des conditions avec « Et », « Ou » et des groupes', en: 'Conditions with “And”, “Or” and groups' },
