  'readerGuide.title': { fr: 'Reliez ce widget à votre tableau', en: 'Link this widget to your table' },
  'readerGuide.intro': { fr: 'En mode Lecture, le modèle se remplit avec la ligne choisie dans un tableau de cette page. Aucune ligne n’arrive à ce widget : il lui faut l’accès complet au document, et il doit être relié à ce tableau par le réglage « Sélectionner par » de Grist.', en: 'In Read mode, the template is filled with the row picked in a table on this page. No row reaches this widget: it needs full access to the document, and it must be linked to that table with Grist’s “Select by” setting.' },
  'readerGuide.step': { fr: 'Étape {n}', en: 'Step {n}' },
